        String html = "<img srcset=\"http://example.com/a.jpg (min-width: 400px, foo: bar), http://example.com/b.jpg 1x\">";
        String clean = Jsoup.clean(html, safelist());
        assertEquals("<img srcset=\"http://example.com/b.jpg 1x\">", clean);
