            case InParens:
                token.append(c); // commas, whitespace, and quotes in here are all literal
                if (c == ')') state = InDescriptor;
                pos++;
                break;
            case AfterDescriptor:
                if (StringUtil.isWhitespace(c)) {
                    pos++;
